const identities = [{"id": "big-dj-bash", "name": "Big DJ Bash", "url": "https://www.behance.net/gallery/126326533/Big-dj-bash", "images": ["https://mir-s3-cdn-cf.behance.net/project_modules/fs_webp/4af19d126326533.612b796a854e6.png"], "line": "An identity with the volume turned up.", "description": "A bold monochrome identity for Big DJ Bash, carried from the logotype into a music discovery and ticketing app.", "tags": ["Visual identity", "Typography", "App design"], "color": "#171923", "artwork": [{"src": "/assets/branding/big-dj-bash-1.webp", "width": 1600, "height": 6484}]}, {"id": "accelscale", "name": "accelScale", "url": "https://www.behance.net/gallery/125709979/accelScale", "images": ["https://mir-s3-cdn-cf.behance.net/project_modules/fs_webp/99417f125709979.611e77fb94129.png"], "line": "Built around forward motion.", "description": "A sharp visual language built from angular forms, a restrained blue palette and a consistent set of stationery applications.", "tags": ["Logo design", "Visual identity", "Stationery"], "color": "#345a99", "artwork": [{"src": "/assets/branding/accelscale-1.webp", "width": 1600, "height": 7084}]}, {"id": "furr", "name": "Furr", "url": "https://www.behance.net/gallery/126159677/Furr", "images": ["https://mir-s3-cdn-cf.behance.net/project_modules/fs_webp/46b8c1126159677.61279c8a8caba.png"], "line": "A little colour. A lot of personality.", "description": "A playful world for Furr by Pee Safe, connecting a colourful visual system with product imagery and expressive social content.", "tags": ["Visual language", "Product imagery", "Social design"], "color": "#58aaa4", "artwork": [{"src": "/assets/branding/furr-1.webp", "width": 1600, "height": 7790}]}, {"id": "domina", "name": "Domina", "url": "https://www.behance.net/gallery/125693089/Domina", "images": ["https://mir-s3-cdn-cf.behance.net/project_modules/fs_webp/f3684e125693089.611e3c46337e3.png", "https://mir-s3-cdn-cf.behance.net/project_modules/1400_webp/094a3c125693089.611e3bc454cb0.png", "https://mir-s3-cdn-cf.behance.net/project_modules/1400_webp/92b8f1125693089.611e3bc454016.png"], "line": "Confidence, by design.", "description": "A soft lavender palette meets confident typography and product communication for Domina by Pee Safe.", "tags": ["Brand language", "Product imagery", "Communication"], "color": "#af83be", "artwork": [{"src": "/assets/branding/domina-1.webp", "width": 1600, "height": 4039}, {"src": "/assets/branding/domina-2.webp", "width": 1400, "height": 2282}, {"src": "/assets/branding/domina-3.webp", "width": 1400, "height": 1032}]}, {"id": "status-tag", "name": "Status Tag", "url": "https://www.behance.net/gallery/126301079/Status-Tag", "images": ["https://mir-s3-cdn-cf.behance.net/project_modules/fs_webp/e1fb37126301079.612a9ad489061.png"], "line": "Making connections look good.", "description": "An identity for a social networking platform, taking its location-inspired symbol and purple palette into the digital experience.", "tags": ["Visual identity", "Colour system", "UI design"], "color": "#9b78d4", "artwork": [{"src": "/assets/branding/status-tag-1.webp", "width": 1600, "height": 5963}]}];
const dialog=document.getElementById('identity-dialog');
const detailScroll=document.querySelector('.detail-scroll');
let activeIndex=0,returnFocus=null;
function showIdentity(index){
 activeIndex=(index+identities.length)%identities.length;
 const project=identities[activeIndex];
 document.getElementById('detail-position').textContent=String(activeIndex+1).padStart(2,'0')+' / 05 — '+project.name.toUpperCase();
 document.getElementById('detail-title').textContent=project.name;
 document.getElementById('detail-description').textContent=project.description;
 const tags=document.getElementById('detail-tags');tags.replaceChildren(...project.tags.map(text=>{const span=document.createElement('span');span.textContent=text;return span}));
 const artwork=document.getElementById('detail-artwork');artwork.replaceChildren(...project.artwork.map((asset,i)=>{const img=document.createElement('img');img.src=asset.src;img.width=asset.width;img.height=asset.height;img.alt=project.name+' — original identity presentation, board '+(i+1);img.loading=i?'lazy':'eager';return img}));
 document.getElementById('detail-source').href=project.url;
 document.querySelector('#detail-next b').textContent=identities[(activeIndex+1)%identities.length].name;
 if(!dialog.open){returnFocus=document.querySelector('[data-identity="'+project.id+'"]');dialog.showModal();document.body.classList.add('project-open');}
 detailScroll.scrollTop=0;
 history.replaceState(null,'','#'+project.id);
 document.getElementById('detail-close').focus({preventScroll:true});
}
document.querySelectorAll('[data-identity]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();showIdentity(identities.findIndex(p=>p.id===link.dataset.identity));}));
document.getElementById('detail-close').addEventListener('click',()=>dialog.close());
document.getElementById('detail-next').addEventListener('click',()=>showIdentity(activeIndex+1));
dialog.addEventListener('click',event=>{if(event.target===dialog){const box=dialog.getBoundingClientRect();if(event.clientX<box.left||event.clientX>box.right||event.clientY<box.top||event.clientY>box.bottom)dialog.close();}});
dialog.addEventListener('close',()=>{document.body.classList.remove('project-open');history.replaceState(null,'',location.pathname+location.search);returnFocus?.focus({preventScroll:true});});
function openHash(){const i=identities.findIndex(p=>p.id===location.hash.slice(1));if(i>=0)showIdentity(i);}
window.addEventListener('hashchange',openHash);openHash();
document.getElementById('year').textContent=new Date().getFullYear();
